{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Sound Bath Events</title>
  <meta name="description" content="Immersive sound bath experiences blending crystal bowls, gong, chimes and breathwork. VIP Day and regular events in {{CITY}}, {{STATE}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body class="layout-bold-playful">
  <svg class="bg-pattern" aria-hidden="true" focusable="false">
    <defs>
      <pattern id="p" patternUnits="userSpaceOnUse" width="200" height="200">
        <image href="assets/img/pattern.svg" width="200" height="200" />
      </pattern>
      <linearGradient id="g1" x1="0" x2="1">
        <stop offset="0" stop-color="#FFFBF0" />
        <stop offset="1" stop-color="#F0F8FF" />
      </linearGradient>
    </defs>
    <rect width="100%" height="100%" fill="url(#p)" opacity="0.12"></rect>
  </svg>

  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav">
        <a href="events.html">Gatherings</a>
        <a href="private-sessions.html">Private Session</a>
        <a href="pricing.html">Pricing &amp; Book</a>
        <a href="about.html">Our Story</a>
        <a href="faq.html">FAQ</a>
        <a class="cta" href="book.html">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
      <button class="menu-toggle" aria-expanded="false">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section id="hero" class="hero">
      <div class="wrap hero-inner">
        <div class="hero-copy">
          <h1>Deep listening. Deliberate rest.</h1>
          <p class="lead">A sensory, premium sound bath combining crystal bowls, gong, and subtle harmonic instruments to guide you into restorative presence.</p>
          <div class="hero-cta">
            <a class="btn primary" href="events.html">See next event — {{NEXT_EVENT_DATE}}</a>
            <a class="btn ghost" href="private-sessions.html">Private options</a>
          </div>
          <p class="meta">Small groups • Intimate acoustics • Facilitated by {{FACILITATOR_NAME}} at {{VENUE_NAME}} in {{CITY}}, {{STATE}}</p>
        </div>
        <div class="hero-visual" aria-hidden="true">
          <div class="orb">
            <svg viewBox="0 0 200 200" class="orb-svg"><defs><radialGradient id="rg"><stop offset="0%" stop-color="#FFF3E8"/><stop offset="100%" stop-color="#E8F7FF"/></radialGradient></defs><circle cx="100" cy="100" r="90" fill="url(#rg)"/></svg>
          </div>
        </div>
      </div>
    </section>

    <!-- DIAGNOSTIC -->
    <section id="diagnostic" class="panel diagnostic">
      <div class="wrap">
        <h2>Is this right for you? A quick check</h2>
        <p class="sub">A few practical signals help you decide if a sound bath is beneficial today.</p>
        <ul class="checklist" id="diagnostic-list">
          <li><label><input type="checkbox"> I'm comfortable lying on a mat for 45–75 minutes</label></li>
          <li><label><input type="checkbox"> I can be in a quiet, dim space without interruption</label></li>
          <li><label><input type="checkbox"> I want to try breathwork + guided sound for nervous system regulation</label></li>
          <li><label><input type="checkbox"> I accept that intense emotions may arise and be held safely</label></li>
        </ul>
        <div class="diag-actions">
          <button id="diag-evaluate" class="btn">Evaluate</button>
          <p id="diag-result" class="note"></p>
        </div>
        <div class="contra">
          <h3>Contraindications &amp; safety</h3>
          <p>Sound baths are gentle but note: if you have epilepsy, recent head injury, unmanaged severe psychiatric conditions, or are pregnant with specific concerns, please consult your physician and reach out to us before booking.</p>
        </div>
      </div>
    </section>

    <!-- PLAN (VIP DAY offer model) -->
    <section id="plan" class="panel plan">
      <div class="wrap two-col">
        <div>
          <h2>VIP Day: Immersive private journey</h2>
          <p class="sub">A curated day for deep recalibration — designed as a single transformative session for individuals or small groups.</p>
          <ol class="flow">
            <li><strong>Intake & Intention:</strong> Intake conversation; set outcomes and safety notes.</li>
            <li><strong>Preparatory Breath + Movement:</strong> Gentle somatics to open the body.</li>
            <li><strong>Sound Immersion:</strong> 60–90 minutes using crystal singing bowls, gong, monochord and tuned chimes to shift brain state.</li>
            <li><strong>Integration & Tea:</strong> Time to rest, journal, and receive aftercare steps.</li>
          </ol>
        </div>
        <aside>
          <div class="card">
            <h3>What to expect in a VIP Day</h3>
            <ul>
              <li>Private space & premium acoustics</li>
              <li>Personalized instrument blend (bowls, tuning forks, chimes)</li>
              <li>30–60 minute post-session integration</li>
            </ul>
            <p class="muted">Perfect for deep-care, creative reset, and bespoke corporate wellness.</p>
            <a class="btn" href="book.html">Book a VIP Day</a>
          </div>
        </aside>
      </div>
    </section>

    <!-- MICRO HABITS -->
    <section id="micro_habits" class="panel micro-habits">
      <div class="wrap">
        <h2>Daily micro-habits to carry the sound home</h2>
        <p class="sub">Three small practices to stabilize the nervous system between events.</p>
        <div class="grid">
          <div class="micro">
            <h4>2-minute bell pause</h4>
            <p>Ring a small tuning fork or bell. Close your eyes and follow the vibration until it fades. Repeat twice.</p>
          </div>
          <div class="micro">
            <h4>Evening body scan</h4>
            <p>Lying in bed, take 6 slow breaths and scan from toes to crown, noticing tension without fixing it.</p>
          </div>
          <div class="micro">
            <h4>Breath rhythm reset</h4>
            <p>4 seconds inhale, 6 seconds exhale — repeat for five cycles to shift into parasympathetic mode.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- PRICING -->
    <section id="pricing" class="panel pricing">
      <div class="wrap">
        <h2>Simple pricing for luminous care</h2>
        <p class="sub">Transparent options. Book a spot at a public sound bath or reserve an intimate private session.</p>
        <div class="pricing-grid">
          <div class="price-card">
            <h3>Public Sound Bath</h3>
            <p class="price">$35–$45</p>
            <p>Group sessions (45–75 minutes). Includes mats and blankets.</p>
            <a class="btn" href="events.html">See events</a>
          </div>
          <div class="price-card highlight">
            <h3>Private 1:1</h3>
            <p class="price">$250 — VIP Day add-on available</p>
            <p>Individualized session using tuning forks, crystal bowls, and guided integration.</p>
            <a class="btn" href="private-sessions.html">Private options</a>
          </div>
          <div class="price-card">
            <h3>Couples &amp; Small Group</h3>
            <p class="price">$350–$600</p>
            <p>Shared private space for healing and team-building.</p>
            <a class="btn" href="contact.html">Inquire</a>
          </div>
        </div>
        <p class="disclaimer">All prices subject to change. Travel and venue fees may apply for off-site sessions.</p>
      </div>
    </section>

    <!-- CTA -->
    <section id="cta" class="panel cta">
      <div class="wrap">
        <div class="cta-inner">
          <h2>Ready for a deeper pause?</h2>
          <p class="sub">Reserve your place or request a private VIP Day. We prioritize intention and safety for every participant.</p>
          <div class="cta-actions">
            <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="contact.html">Contact: {{EMAIL}}</a>
          </div>
          <p class="small">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="foot-left">
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{TAGLINE}}</p>
        <p>{{VENUE_NAME}} — {{CITY}}, {{STATE}}</p>
      </div>
      <div class="foot-right">
        <nav>
          <a href="events.html">Events</a>
          <a href="about.html">About</a>
          <a href="faq.html">FAQ</a>
          <a href="contact.html">Contact</a>
        </nav>
        <p class="muted">© <span id="year"></span> {{BUSINESS_NAME}}. All rights reserved.</p>
      </div>
    </div>
  </footer>

</body>
</html>"} 
