{"path":"assets/css/styles.css","content":"/* Bold + playful sound bath theme - no external fonts */
:root{
  --bg:#0f1720;
  --card:#fffdf9;
  --accent:#6aa6ff;
  --accent-2:#ff9fb4;
  --muted:#6b7280;
  --radius:14px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial; margin:0; color:#0b1220; background:linear-gradient(180deg,var(--card),#f6fbff);}
.wrap{max-width:1100px;margin:0 auto;padding:28px}
.site-header{position:sticky;top:0;background:rgba(255,255,255,0.6);backdrop-filter:blur(6px);border-bottom:1px solid rgba(10,10,10,0.03)}
.site-header .wrap{display:flex;align-items:center;gap:18px}
.brand{font-weight:800;color:#0b1220;text-decoration:none;font-size:1.1rem}
.nav{margin-left:auto;display:flex;gap:12px;align-items:center}
.nav a{color:#0b1220;text-decoration:none;padding:8px 12px;border-radius:8px;font-weight:600}
.nav a.cta{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white}
.menu-toggle{display:none;background:none;border:0;font-size:1.2rem}
.bg-pattern{position:fixed;inset:0;pointer-events:none;z-index:-1}
.hero{padding:56px 0}
.hero-inner{display:flex;align-items:center;gap:24px}
.hero-copy{flex:1}
.hero h1{font-size:clamp(28px,5vw,44px);margin:0 0 8px}
.lead{color:var(--muted);margin:0 0 16px}
.hero-cta{display:flex;gap:12px;margin:16px 0}
.btn{display:inline-block;padding:10px 16px;border-radius:10px;text-decoration:none;border:0;background:#f3f7ff;color:#0b1220;font-weight:700}
.btn.ghost{background:transparent;border:2px solid rgba(11,18,32,0.05)}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white}
.btn.large{padding:14px 22px;font-size:1.05rem}
.hero-visual{width:280px;display:flex;justify-content:center}
.orb{width:220px;height:220px;border-radius:50%;box-shadow:0 12px 40px rgba(10,18,30,0.12);display:flex;align-items:center;justify-content:center;background:radial-gradient(circle at 30% 30%,#fff9f2, #eef8ff)}
.orb-svg{width:160px;height:160px}
.meta{font-size:0.9rem;color:var(--muted)}
.panel{padding:36px 0}
.diagnostic .checklist{display:grid;gap:8px;padding:0;margin:12px 0 0 0;list-style:none}
.diagnostic label{display:flex;gap:8px;align-items:center}
.diag-actions{margin-top:12px;display:flex;gap:12px;align-items:center}
.note{color:var(--muted);margin:0}
.contra{margin-top:18px;background:linear-gradient(180deg,#fff, #fbfbff);padding:14px;border-radius:12px;border:1px solid rgba(11,18,32,0.04)}
.two-col{display:grid;grid-template-columns:1fr 320px;gap:20px;align-items:start}
.card{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 8px 30px rgba(12,20,30,0.06)}
.flow{padding-left:18px}
.micro-habits .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px}
.micro{background:#fff;border-radius:12px;padding:16px;box-shadow:0 6px 20px rgba(10,14,20,0.04)}
.pricing-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin-top:16px}
.price-card{background:#fff;padding:18px;border-radius:12px;border:1px solid rgba(11,18,32,0.04)}
.price-card.highlight{border:3px solid rgba(106,166,255,0.22);box-shadow:0 12px 40px rgba(106,166,255,0.06)}
.price{font-weight:800;font-size:1.4rem;margin:8px 0}
.disclaimer{color:var(--muted);font-size:0.9rem;margin-top:8px}
.cta{background:linear-gradient(90deg,#fff6f2,#f3fbff);border-radius:18px}
.cta-inner{display:flex;flex-direction:column;align-items:flex-start;gap:12px}
.site-footer{border-top:1px solid rgba(10,10,10,0.03);background:transparent;padding:22px 0}
.site-footer .wrap{display:flex;justify-content:space-between;align-items:center}
.foot-left p{margin:6px 0}
.foot-right nav{display:flex;gap:12px}
.muted{color:var(--muted)}
.small{font-size:0.85rem;color:var(--muted)}
/* Responsive */
@media (max-width:900px){
  .hero-inner{flex-direction:column-reverse}
  .two-col{grid-template-columns:1fr}
  .menu-toggle{display:block}
  .nav{display:none}
}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // mobile menu
  var btn=document.querySelector('.menu-toggle');
  var nav=document.querySelector('.nav');
  if(btn){btn.addEventListener('click',function(){
    var expanded = this.getAttribute('aria-expanded') === 'true';
    this.setAttribute('aria-expanded', (!expanded).toString());
    nav.style.display = expanded ? 'none' : 'flex';
  });}

  // diagnostic evaluate
  var evalBtn = document.getElementById('diag-evaluate');
  if(evalBtn){
    evalBtn.addEventListener('click',function(){
      var checks = Array.from(document.querySelectorAll('#diagnostic-list input[type="checkbox"]'));
      var count = checks.filter(function(c){return c.checked}).length;
      var out = document.getElementById('diag-result');
      if(count>=3){ out.textContent = 'This experience is likely a great fit for you today. Consider booking or reaching out if you have specific health questions.' }
      else{ out.textContent = 'You may prefer a private 1:1 session or to try short micro-practices first. Contact us to discuss adaptations.' }
    });
  }

  // set year
  var y=document.getElementById('year'); if(y) y.textContent = new Date().getFullYear();

  // smooth anchor links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      e.preventDefault(); document.querySelector(this.getAttribute('href')).scrollIntoView({behavior:'smooth'});
    });
  });
});"} 
